(216588, 12748, 6202, '<td valign="top">as I was going through all the photos this one brought a smile to my face simply for being orginal.</td>', 'as I was going through all the photos this one brought a smile to my face simply for being orginal.', '2003-02-17 00:17:16.000000', NULL, 1),
(216591, 12498, 772, '<td valign="top">this is a great shot of repeating patterns for sure... excellent ''rhythm''... I believe it may be slightly oversharpened possibly... there are some ''jags'' in the foreground part of the slinky that indicate this... great shot.. = 8 - setzler</td>', 'this is a great shot of repeating patterns for sure... excellent ''rhythm''... I believe it may be slightly oversharpened possibly... there are some ''jags'' in the foreground part of the slinky that indicate this... great shot.. = 8 - setzler', '2003-02-17 00:17:54.000000', NULL, 1),
