(216616, 12654, 3607, '<td valign="top">the motif is good but its just not a compelling photo . . .</td>', 'the motif is good but its just not a compelling photo . . .', '2003-02-17 00:29:42.000000', NULL, 1),
(216617, 12462, 3102, '<td valign="top">A great idea and interesting composition, but it seems to lack a bit of clarity.  I see that the image is about 72K... which is only about half of what DPC allows -- you might try saving it at a lower .jpg compression.  The bottom part of the shot seems just a tad dark.</td>', 'A great idea and interesting composition, but it seems to lack a bit of clarity.  I see that the image is about 72K... which is only about half of what DPC allows -- you might try saving it at a lower .jpg compression.  The bottom part of the shot seems just a tad dark.', '2003-02-17 00:29:58.000000', NULL, 1),
(216621, 12462, 3607, '<td valign="top">i don''t think the boats or the sunset were cooperating very well - it would be awesome another day, but not this day . . .</td>', 'i don''t think the boats or the sunset were cooperating very well - it would be awesome another day, but not this day . . .', '2003-02-17 00:30:46.000000', NULL, 1),
