(216744, 12663, 6696, '<td valign="top">Rythm is a stretch.</td>', 'Rythm is a stretch.', '2003-02-17 01:04:07.000000', NULL, 1),
(216746, 12607, 3900, '<td valign="top">Rhythm in ripples.  Or coordinated swimming?  Good composition, but could stand a bit sharper focus and richer color.</td>', 'Rhythm in ripples.  Or coordinated swimming?  Good composition, but could stand a bit sharper focus and richer color.', '2003-02-17 01:04:35.000000', NULL, 1),
