(221234, 12568, 772, '<td valign="top">excellent composition and great work with the motion blur :) - setzler</td>', 'excellent composition and great work with the motion blur :) - setzler', '2003-02-22 19:00:27.000000', NULL, 1),
(221239, 12636, 5728, '<td valign="top">I''m still trying to figure out what those things are! Some kind of spindles right? The crop is excellent and the colour is awesome. My eyes keep being drawn into the middle. This is really rhythm, I like it and hope you do well with it.</td>', 'I''m still trying to figure out what those things are! Some kind of spindles right? The crop is excellent and the colour is awesome. My eyes keep being drawn into the middle. This is really rhythm, I like it and hope you do well with it.', '2003-02-22 19:11:09.000000', NULL, 1),
(221240, 12373, 5728, '<td valign="top">This is rhythm for sure although I don''t really see what it is, I hope you explain it in your description! It looks very frosty for some reason, maybe a little too dark on the right but I guess if you had made it any lighter the left side would have blown out too much.</td>', 'This is rhythm for sure although I don''t really see what it is, I hope you explain it in your description! It looks very frosty for some reason, maybe a little too dark on the right but I guess if you had made it any lighter the left side would have blown out too much.', '2003-02-22 19:13:39.000000', NULL, 1),
(221241, 12673, 5728, '<td valign="top">I like how you got both those ducks in synchronisation, it is the main charachter in this image. The trees look as if it is very windy. Good crop here but maybe the´focus could have been a tad better on those ducks. Good capture.</td>', 'I like how you got both those ducks in synchronisation, it is the main charachter in this image. The trees look as if it is very windy. Good crop here but maybe the´focus could have been a tad better on those ducks. Good capture.', '2003-02-22 19:16:20.000000', NULL, 1),
(221242, 12654, 5728, '<td valign="top">Great capture here, it truly meets the rhythm challenge. The crop is great. Somehow a little grainy though and personally I would have cropped out that dark bit on the bottom step. Otherwise a good photo!</td>', 'Great capture here, it truly meets the rhythm challenge. The crop is great. Somehow a little grainy though and personally I would have cropped out that dark bit on the bottom step. Otherwise a good photo!', '2003-02-22 19:18:55.000000', NULL, 1),
(221245, 12368, 3032, '<td valign="top">Excellent composition. Wonderful how the leafes work out when refracted by the water. Wonderful flowing curves and great gradations of colors. This one is 200% better as the yellow entry.</td>', 'Excellent composition. Wonderful how the leafes work out when refracted by the water. Wonderful flowing curves and great gradations of colors. This one is 200% better as the yellow entry.', '2003-02-22 19:21:00.000000', NULL, 1),
(221247, 12347, 5728, '<td valign="top">Nice rhythm! The sky looks as if a storm is coming over from the right. I find the blue sky a little too grainy up at the top left although the clouds don''t reveal it so much so I guess it comes from saving for the web. The border fits and the title fits, good job!</td>', 'Nice rhythm! The sky looks as if a storm is coming over from the right. I find the blue sky a little too grainy up at the top left although the clouds don''t reveal it so much so I guess it comes from saving for the web. The border fits and the title fits, good job!', '2003-02-22 19:22:24.000000', NULL, 1),
(221263, 12745, 3032, '<td valign="top">The perspective, use of aperture and color of this shot are wonderful. <br/>The background provides good contrast, but the lower right surface is pretty ugly. The white border doesn work very well.<br/> <br/>Composition and color makes this a good photo.</td>', 'The perspective, use of aperture and color of this shot are wonderful. The background provides good contrast, but the lower right surface is pretty ugly. The white border doesn work very well. Composition and color makes this a good photo.', '2003-02-22 19:25:51.000000', NULL, 1),
(221265, 12589, 5728, '<td valign="top">That''s rhythm! I wanted to do a flag photo myself but couldn''t find a row of them like you did. The sky would have come out a lot better using a polarize filter for sure, but I don''t have one of those myself yet. Next on my list of things to buy! A nice long crop here and you''ve made it look very windy. Good job!</td>', 'That''s rhythm! I wanted to do a flag photo myself but couldn''t find a row of them like you did. The sky would have come out a lot better using a polarize filter for sure, but I don''t have one of those myself yet. Next on my list of things to buy! A nice long crop here and you''ve made it look very windy. Good job!', '2003-02-22 19:26:03.000000', NULL, 1),
(221271, 12658, 3032, '<td valign="top">Nice how the shadows work with the tiles and how there seem to be color patterns all over the place. The diagonal composition of the tiles provides good depth. Color, sharpness, aperture choice and exposure are excellent.</td>', 'Nice how the shadows work with the tiles and how there seem to be color patterns all over the place. The diagonal composition of the tiles provides good depth. Color, sharpness, aperture choice and exposure are excellent.', '2003-02-22 19:27:59.000000', NULL, 1),
(221279, 12394, 5728, '<td valign="top">Wonderful! I get this effect with Xenofex in Photoshop but not nearly as good as you shot it! You make it look dangerous to walk over it! Great capture, you have brought life into this shot!</td>', 'Wonderful! I get this effect with Xenofex in Photoshop but not nearly as good as you shot it! You make it look dangerous to walk over it! Great capture, you have brought life into this shot!', '2003-02-22 19:29:58.000000', NULL, 1),
(221284, 12596, 3032, '<td valign="top">Cool how there seems to be grey vs color and nice use of diagonals in the composition. A smaller aperture to make all the spools sharp or a wider aperture to lock the field of focus on only one or two spools (preferably blue or red) would have given this a much greater impact.<br/>Anyway, great photo, like the worn look, makes them look very old. Not so enthousiastic about the border, but that doesn''t count.</td>', 'Cool how there seems to be grey vs color and nice use of diagonals in the composition. A smaller aperture to make all the spools sharp or a wider aperture to lock the field of focus on only one or two spools (preferably blue or red) would have given this a much greater impact.Anyway, great photo, like the worn look, makes them look very old. Not so enthousiastic about the border, but that doesn''t count.', '2003-02-22 19:32:52.000000', NULL, 1),
(221287, 12625, 3032, '<td valign="top">Lovely compsotion, but it is bit soft for my liking.</td>', 'Lovely compsotion, but it is bit soft for my liking.', '2003-02-22 19:33:52.000000', NULL, 1),
(221295, 12602, 3032, '<td valign="top">Good use of diagonals and the expression of motion is save by the water effects at the and of the rowing thingies. Good B&amp;W.</td>', 'Good use of diagonals and the expression of motion is save by the water effects at the and of the rowing thingies. Good B&W.', '2003-02-22 19:35:44.000000', NULL, 1),
(221301, 12736, 3032, '<td valign="top">Good composition, diagonals add a lot of depth.<br/>The crop is too tight though.</td>', 'Good composition, diagonals add a lot of depth.The crop is too tight though.', '2003-02-22 19:37:36.000000', NULL, 1),
(221311, 12568, 5728, '<td valign="top">Ah rhythm in a blur, nice idea with the drumming. The crop is good. There seem to be too many white spots in the top left hand corner though. The effect is good.</td>', 'Ah rhythm in a blur, nice idea with the drumming. The crop is good. There seem to be too many white spots in the top left hand corner though. The effect is good.', '2003-02-22 19:42:06.000000', NULL, 1),
(221316, 12646, 3447, '<td valign="top">Burnout to blackout.  However, it is a photo of interest and I give it a high vote.<br/></td>', 'Burnout to blackout.  However, it is a photo of interest and I give it a high vote.', '2003-02-22 19:44:28.000000', NULL, 1),
(221319, 12607, 5728, '<td valign="top">You''ve cropped this one excellently, I like the flow off to the left, good capture. I think maybe a little more focus on the ducks would have enhanced this image a lot more. You got a wonderful green out of the water there!</td>', 'You''ve cropped this one excellently, I like the flow off to the left, good capture. I think maybe a little more focus on the ducks would have enhanced this image a lot more. You got a wonderful green out of the water there!', '2003-02-22 19:44:59.000000', NULL, 1),
(221326, 12766, 5728, '<td valign="top">Lovely structure! it is rhythm for sure and meets the challenge. A little more focus would have been better to bring out the sharpness in those leaves. The colours are so natural.</td>', 'Lovely structure! it is rhythm for sure and meets the challenge. A little more focus would have been better to bring out the sharpness in those leaves. The colours are so natural.', '2003-02-22 19:47:38.000000', NULL, 1),
(221329, 12636, 3447, '<td valign="top">Good angle, good color and meets challenge but, oh boy, are you going to feel the heat from those who think all meat is born in shrink wrap plastic.</td>', 'Good angle, good color and meets challenge but, oh boy, are you going to feel the heat from those who think all meat is born in shrink wrap plastic.', '2003-02-22 19:49:00.000000', NULL, 1),
(221332, 12764, 5728, '<td valign="top">You got that sky looking stormy there! The vinerows are a little to dark, but I guess if you had tried to lighten them more the sky would have blown out so there isn''t much you could have done here. Maybe if you had gone more to the right and taken the photo at a different angle you could have gotten a lighter field.</td>', 'You got that sky looking stormy there! The vinerows are a little to dark, but I guess if you had tried to lighten them more the sky would have blown out so there isn''t much you could have done here. Maybe if you had gone more to the right and taken the photo at a different angle you could have gotten a lighter field.', '2003-02-22 19:50:47.000000', NULL, 1),
(221335, 12603, 5728, '<td valign="top">Did you ask those gulls to stand there like that??? Cool! If this photo had been more in focus it would have enhanced it emmensly, the sharpness is missing.</td>', 'Did you ask those gulls to stand there like that??? Cool! If this photo had been more in focus it would have enhanced it emmensly, the sharpness is missing.', '2003-02-22 19:53:19.000000', NULL, 1),
(221338, 12725, 5728, '<td valign="top">Ah Las Vegas??? It''s a rhythm shot for sure. If you got the million showing on those machines please remember me at Christmas! It''s a good crop, maybe a little too dark. I would have opened the aperture up a lot more here to get all those machines in focus. Good capture!</td>', 'Ah Las Vegas??? It''s a rhythm shot for sure. If you got the million showing on those machines please remember me at Christmas! It''s a good crop, maybe a little too dark. I would have opened the aperture up a lot more here to get all those machines in focus. Good capture!', '2003-02-22 19:56:30.000000', NULL, 1),
(221344, 12660, 5728, '<td valign="top">You got me hungry for Chinese food now, thanx! This meets the challenge with the rhythm on those signs, the shadows bother me a little however but in a a way they also bring a little charachter into the image. The blue sky complemenst the other colors weel. And the fact you didn''t put a border on this photo was good, it would have only lowered its impact.</td>', 'You got me hungry for Chinese food now, thanx! This meets the challenge with the rhythm on those signs, the shadows bother me a little however but in a a way they also bring a little charachter into the image. The blue sky complemenst the other colors weel. And the fact you didn''t put a border on this photo was good, it would have only lowered its impact.', '2003-02-22 20:00:42.000000', NULL, 1),
(221346, 12650, 5728, '<td valign="top">Okay I''ll agree it is rhythm. It is a wonderful crop, I like the way you left so much snow to the right of the image, it enhances it a lot. Good one!</td>', 'Okay I''ll agree it is rhythm. It is a wonderful crop, I like the way you left so much snow to the right of the image, it enhances it a lot. Good one!', '2003-02-22 20:02:43.000000', NULL, 1),
(221349, 12717, 5728, '<td valign="top">Ah rhythm is two ways here, one as music and one as form, good one! The light seems a little too bright on some parts of the instrument, was it a flash? The crop is good here!</td>', 'Ah rhythm is two ways here, one as music and one as form, good one! The light seems a little too bright on some parts of the instrument, was it a flash? The crop is good here!', '2003-02-22 20:06:08.000000', NULL, 1),
(221350, 12371, 2716, '<td valign="top">Quelle belle photo.  J''adore les couleurs et les belles vagues.  Très original.  Bonne et chance mon ami.</td>', 'Quelle belle photo.  J''adore les couleurs et les belles vagues.  Très original.  Bonne et chance mon ami.', '2003-02-22 20:06:25.000000', NULL, 1),
(221353, 12620, 5728, '<td valign="top">What a cool mossy roof! Wonderul colors here, and the crop is good, you got those reds and yellows mixing perfectly together. Personally I would have gone more to the right and cropped out that rooftop on the far left. You could have gotten an excellent unbroken rhythm shot. Good one!</td>', 'What a cool mossy roof! Wonderul colors here, and the crop is good, you got those reds and yellows mixing perfectly together. Personally I would have gone more to the right and cropped out that rooftop on the far left. You could have gotten an excellent unbroken rhythm shot. Good one!', '2003-02-22 20:09:46.000000', NULL, 1),
(221356, 12420, 5728, '<td valign="top">I wanted to do this but couldn''t get over the fence to get one the power station! You were lucky and got one close to the fence! Nice rhythm! I would have dropped the fence out though, it is kind of disturbing, you should have gone a little higher! The lamp fits in perfectly though.</td>', 'I wanted to do this but couldn''t get over the fence to get one the power station! You were lucky and got one close to the fence! Nice rhythm! I would have dropped the fence out though, it is kind of disturbing, you should have gone a little higher! The lamp fits in perfectly though.', '2003-02-22 20:12:47.000000', NULL, 1),
(221357, 12426, 5728, '<td valign="top">It''s a great shot and a wonderful idea. The only thing that really bothers me is the focus, it just doesn''t seem sharp enough. The lighting is perfect and the black background just melts into the blue.</td>', 'It''s a great shot and a wonderful idea. The only thing that really bothers me is the focus, it just doesn''t seem sharp enough. The lighting is perfect and the black background just melts into the blue.', '2003-02-22 20:15:41.000000', NULL, 1),
(221358, 12625, 5728, '<td valign="top">I love it! The crop is excellent and the lights follow the form of the girl''s back. The crop is good and the challenge is met for sure! You did well to do this one in black and white. Does the girl have a phone number?</td>', 'I love it! The crop is excellent and the lights follow the form of the girl''s back. The crop is good and the challenge is met for sure! You did well to do this one in black and white. Does the girl have a phone number?', '2003-02-22 20:17:55.000000', NULL, 1),
(221359, 12696, 6537, '<td valign="top">I like this image its simple, and there a feeling of ryhthm.</td>', 'I like this image its simple, and there a feeling of ryhthm.', '2003-02-22 20:40:36.000000', NULL, 1),
(221426, 12745, 2716, '<td valign="top">Great!  love the alternating colours.  Jakco.  8</td>', 'Great!  love the alternating colours.  Jakco.  8', '2003-02-22 22:58:27.000000', NULL, 1),
(221475, 12745, 6325, '<td valign="top">I can almost taste them! Good shot overall. You captured the "wetness" of the melons ver well. I wish the table suface could have been more uniform - more lighting or a less reflective surface. 8</td>', 'I can almost taste them! Good shot overall. You captured the "wetness" of the melons ver well. I wish the table suface could have been more uniform - more lighting or a less reflective surface. 8', '2003-02-23 00:29:59.000000', NULL, 1),
(221476, 12629, 6325, '<td valign="top">I like the very high contrast. It works in this photo. The lose of detail is OK in this instance.</td>', 'I like the very high contrast. It works in this photo. The lose of detail is OK in this instance.', '2003-02-23 00:31:58.000000', NULL, 1),
(221480, 12347, 6325, '<td valign="top">Good composition and subject for ''Rhythms"  More punch in the whites and blacker blacks would have bumped it up.</td>', 'Good composition and subject for ''Rhythms"  More punch in the whites and blacker blacks would have bumped it up.', '2003-02-23 00:33:49.000000', NULL, 1),
(221486, 12752, 6325, '<td valign="top">Good job of achieving overall dof.</td>', 'Good job of achieving overall dof.', '2003-02-23 00:42:26.000000', NULL, 1),
(221488, 12607, 6325, '<td valign="top">Nice subjects. Nothing is quite in focus.</td>', 'Nice subjects. Nothing is quite in focus.', '2003-02-23 00:43:32.000000', NULL, 1),
(221490, 12368, 6325, '<td valign="top">Like the waves in the glass.</td>', 'Like the waves in the glass.', '2003-02-23 00:47:04.000000', NULL, 1),
(221491, 12688, 6325, '<td valign="top">An unusual sine wave and the ball is changing numbers too. Clever.</td>', 'An unusual sine wave and the ball is changing numbers too. Clever.', '2003-02-23 00:49:19.000000', NULL, 1),
(221504, 12551, 6702, '<td valign="top">Good color, contrast, creativity. Nice work.</td>', 'Good color, contrast, creativity. Nice work.', '2003-02-23 03:17:04.000000', NULL, 1),
(221505, 12596, 6702, '<td valign="top">I really like this picture. The uneven material in the background distracts slightly from the great rhythm of the colored spools. Good work.</td>', 'I really like this picture. The uneven material in the background distracts slightly from the great rhythm of the colored spools. Good work.', '2003-02-23 03:21:12.000000', NULL, 1),
(221506, 12745, 6702, '<td valign="top">I like Melon, Cantaloupe, Honeydew, and your picture. Nice work.</td>', 'I like Melon, Cantaloupe, Honeydew, and your picture. Nice work.', '2003-02-23 03:26:49.000000', NULL, 1),
(221508, 12403, 6702, '<td valign="top">The color, contrast and texture are great. Good Work.</td>', 'The color, contrast and texture are great. Good Work.', '2003-02-23 03:34:49.000000', NULL, 1),
(221509, 12699, 6702, '<td valign="top">Nice work. Good balance, lighting, contrast.</td>', 'Nice work. Good balance, lighting, contrast.', '2003-02-23 03:35:45.000000', NULL, 1),
(221510, 12400, 6702, '<td valign="top">Great idea! Good shutter speed. Nice croping.</td>', 'Great idea! Good shutter speed. Nice croping.', '2003-02-23 03:37:08.000000', NULL, 1),
(221518, 12625, 3585, '<td valign="top">Very nice approach to repetition with different volumes, quite festive as well. 10</td>', 'Very nice approach to repetition with different volumes, quite festive as well. 10', '2003-02-23 09:11:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(221520, 12368, 3585, '<td valign="top">Nice patterns especcially in the glass part, I regret the brown frame that blends everything together. Try replacing it with a white one, it will separate the volumes and amplifie the rythm. 9</td>', 'Nice patterns especcially in the glass part, I regret the brown frame that blends everything together. Try replacing it with a white one, it will separate the volumes and amplifie the rythm. 9', '2003-02-23 09:16:25.000000', NULL, 1),
