(221526, 12752, 3585, '<td valign="top">Nice rythms and good contrast, too bad for the two faint windows(?) that add depth where it is not needed. 9</td>', 'Nice rythms and good contrast, too bad for the two faint windows(?) that add depth where it is not needed. 9', '2003-02-23 09:32:14.000000', NULL, 1),
